=Draft a transaction-related email.

Action needed: {{ $json.action }}
Context: {{ $json.context }}
Property: {{ $json.property_address }}
Buyer: {{ $json.buyer_name }}
Seller: {{ $json.seller_name }}
Other agent email: {{ $json.other_agent_email }}
Closing date: {{ $json.closing_date }}
Inspection date: {{ $json.inspection_date }}
Notes about this deal: {{ $json.notes }}

parameters.jsCode:
const today = new Date();
today.setUTCHours(0, 0, 0, 0);
const todayMs = today.getTime();
const DAY_MS = 24 * 60 * 60 * 1000;

const results = [];

for (const item of $input.all()) {
  const t = item.json;

  // Skip closed transactions
  if (t.status === 'closed') continue;

  let action = null;
  let context = '';

  // Parse milestones (it might be stringified JSON)
  const milestones = typeof t.milestones === 'string' 
    ? JSON.parse(t.milestones) 
    : (t.milestones || {});

  // Check: inspection happening tomorrow or today
  if (t.inspection_date) {
    const inspectionDate = new Date(t.inspection_date);
    inspectionDate.setUTCHours(0, 0, 0, 0);
    const daysUntilInspection = (inspectionDate.getTime() - todayMs) / DAY_MS;

    if (daysUntilInspection === 1) {
      action = 'inspection_tomorrow';
      context = 'Inspection is scheduled for tomorrow';
    } else if (daysUntilInspection === 0 && !milestones.inspection_done) {
      action = 'inspection_today';
      context = 'Inspection is scheduled for today';
    }
  }

  // Check: inspection done but no follow-up sent yet
  if (!action && milestones.inspection_done && !milestones.inspection_follow_up_sent) {
    action = 'inspection_follow_up';
    context = 'Inspection completed, need to follow up with buyer and other agent';
  }

  // Check: closing in 7 days or less
  if (!action && t.closing_date) {
    const closingDate = new Date(t.closing_date);
    closingDate.setUTCHours(0, 0, 0, 0);
    const daysUntilClosing = (closingDate.getTime() - todayMs) / DAY_MS;

    if (daysUntilClosing > 0 && daysUntilClosing <= 7) {
      action = 'closing_soon';
      context = `Closing in ${Math.floor(daysUntilClosing)} day${Math.floor(daysUntilClosing) > 1 ? 's' : ''}`;
    }
  }

  if (action) {
    results.push({
      json: {
        ...t,
        action: action,
        context: context
      }
    });
  }
}

return results;

const results = [];

for (const item of $input.all()) {
  const content = item.json.content[0].text;

  // Find the matching transaction context from earlier in the flow
  // We need to know action, property_address, other_agent_email
  const idx = $input.all().indexOf(item);
  const txn = $('Code').all()[idx].json;

  if (content.includes('---SECOND EMAIL TO OTHER AGENT---')) {
    const [buyerEmail, agentEmail] = content.split('---SECOND EMAIL TO OTHER AGENT---').map(s => s.trim());

    // Email 1: to buyer
    results.push({
      json: {
        body: buyerEmail,
        to: 'buyer@example.com',  // would be buyer's email in production
        recipient_role: 'buyer',
        action: txn.action,
        property_address: txn.property_address
      }
    });

    // Email 2: to other agent
    results.push({
      json: {
        body: agentEmail,
        to: txn.other_agent_email,
        recipient_role: 'other_agent',
        action: txn.action,
        property_address: txn.property_address
      }
    });
  } else {
    // Single email, just pass through
    results.push({
      json: {
        body: content,
        to: 'buyer@example.com',
        recipient_role: 'buyer',
        action: txn.action,
        property_address: txn.property_address
      }
    });
  }
}

return results;

